-- Additive shop v2 (generated by scripts/generate-shop-migration.mjs).
-- Economy: coin rewards ×3 (existing ledger rows included); the four outfits are retired and refunded by no longer
-- counting outfit_purchases as spending. Skins (permanent) and potions (consumable, used inside a boss fight) are added.
update public.quest_definitions set coins=coins*3;
update public.reward_ledger set coins=coins*3;
do $$ declare c record; begin
 for c in select conname from pg_constraint where conrelid='public.practice_log'::regclass and contype='c' and pg_get_constraintdef(oid) like '%coins%' loop
  execute format('alter table public.practice_log drop constraint %I',c.conname); end loop;
end $$;
update public.practice_log set coins=15;
alter table public.practice_log add constraint practice_log_coins_check check(coins=15);

