create table public.item_catalog(id text primary key, price integer not null check(price>0));
insert into public.item_catalog(id,price) values ('hint',150),('heart',200),('reveal',345),('double',750);
alter table public.user_progress add column equipped_skin_id text not null default 'swordsman' references public.skin_catalog(id);
create index user_progress_skin_idx on public.user_progress(equipped_skin_id);
create table public.skin_purchases(user_id uuid not null references public.user_progress(user_id) on delete cascade, skin_id text not null references public.skin_catalog(id),
 coins integer not null check(coins>0), purchased_at timestamptz not null default clock_timestamp(), primary key(user_id,skin_id));
create index skin_purchases_skin_idx on public.skin_purchases(skin_id);
create table public.item_purchases(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.user_progress(user_id) on delete cascade,
 item_id text not null references public.item_catalog(id), qty integer not null check(qty between 1 and 9), coins integer not null check(coins>0),
 purchased_at timestamptz not null default clock_timestamp());
create index item_purchases_user_idx on public.item_purchases(user_id); create index item_purchases_item_idx on public.item_purchases(item_id);
create table public.item_uses(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.user_progress(user_id) on delete cascade,
 item_id text not null references public.item_catalog(id), quest_id text not null references public.quest_definitions(id), battle_id uuid not null,
 used_at timestamptz not null default clock_timestamp());
create index item_uses_user_idx on public.item_uses(user_id,quest_id,battle_id); create index item_uses_item_idx on public.item_uses(item_id); create index item_uses_quest_idx on public.item_uses(quest_id);
alter table public.skin_catalog enable row level security; alter table public.item_catalog enable row level security;
alter table public.skin_purchases enable row level security; alter table public.item_purchases enable row level security; alter table public.item_uses enable row level security;
revoke all on public.skin_catalog,public.item_catalog,public.skin_purchases,public.item_purchases,public.item_uses from public,anon,authenticated;
grant select on public.skin_catalog,public.item_catalog,public.skin_purchases,public.item_purchases,public.item_uses to authenticated;
create policy skin_catalog_read on public.skin_catalog for select to authenticated using(true);
create policy item_catalog_read on public.item_catalog for select to authenticated using(true);
create policy skin_purchases_read on public.skin_purchases for select to authenticated using((select auth.uid())=user_id);
create policy item_purchases_read on public.item_purchases for select to authenticated using((select auth.uid())=user_id);
create policy item_uses_read on public.item_uses for select to authenticated using((select auth.uid())=user_id);

-- Spendable coins: quest ledger + daily practice − skins − potions (outfits refunded).
create function private.funds(u uuid) returns bigint language sql stable security definer set search_path='' as $$
 select (select coalesce(sum(coins),0) from public.reward_ledger where user_id=u)+(select coalesce(sum(coins),0) from public.practice_log where user_id=u)
  -(select coalesce(sum(coins),0) from public.skin_purchases where user_id=u)-(select coalesce(sum(coins),0) from public.item_purchases where user_id=u); $$;
create function private.stock(u uuid, item text) returns bigint language sql stable security definer set search_path='' as $$
 select (select coalesce(sum(qty),0) from public.item_purchases where user_id=u and item_id=item)-(select count(*) from public.item_uses where user_id=u and item_id=item); $$;
revoke all on function private.funds(uuid),private.stock(uuid,text) from public,anon,authenticated;

alter function private.snapshot() rename to snapshot_v6;
revoke all on function private.snapshot_v6() from public,anon,authenticated;
create function private.snapshot() returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;u uuid;skins jsonb;buys jsonb;uses jsonb;
begin
 result:=private.snapshot_v6();u:=auth.uid();
 select coalesce(jsonb_object_agg(skin_id,jsonb_build_object('skinId',skin_id,'coins',coins,'purchasedAt',floor(extract(epoch from purchased_at)*1000)::bigint)),'{}'::jsonb) into skins from public.skin_purchases where user_id=u;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'itemId',item_id,'qty',qty,'coins',coins,'purchasedAt',floor(extract(epoch from purchased_at)*1000)::bigint) order by purchased_at,id),'[]'::jsonb) into buys from public.item_purchases where user_id=u;
 select coalesce(jsonb_agg(jsonb_build_object('itemId',item_id,'questId',quest_id,'battleId',battle_id,'usedAt',floor(extract(epoch from used_at)*1000)::bigint) order by used_at,id),'[]'::jsonb) into uses from public.item_uses where user_id=u;
 return jsonb_set(result,'{progress}',((result->'progress')-'purchases'-'equippedOutfitId')||jsonb_build_object('version',7,'coins',private.funds(u),
  'equippedSkinId',(select equipped_skin_id from public.user_progress where user_id=u),'skins',skins,'itemPurchases',buys,'itemUses',uses));
end $$;
revoke all on function private.snapshot() from public,anon,authenticated;
grant execute on function private.snapshot() to authenticated;

create function private.shop_command(action text,payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;p public.user_progress;price integer;n integer;d integer;h integer;score integer;total integer;battle uuid;c text;t timestamptz;dd date;task text:=payload->>'taskId';
 q text:=payload->>'questId';s text;answers jsonb:=payload->'answers';
begin
 if action in ('purchase','equip') then raise exception 'ITEM_RETIRED';end if;
 if action not in ('buy_skin','equip_skin','buy_item','use_item','boss_attempt','practice') then return private.growth_command(action,payload);end if;
 u:=private.ensure_user(); -- row lock serialises spending and potion use
 select * into p from public.user_progress where user_id=u;
 if action='practice' then -- same rules as daily_practice, at the tripled reward
  c:=p.career_id;
  if c is null then raise exception 'PRACTICE_CAREER_REQUIRED';end if;
  if not exists(select 1 from public.career_tasks where career_id=c and id=task)then raise exception 'PRACTICE_TASK_INVALID';end if;
  t:=clock_timestamp();dd:=(t at time zone 'Asia/Bangkok')::date;
  if exists(select 1 from public.practice_log where user_id=u and practice_day=dd and career_id=c and task_id=task)then return private.snapshot();end if;
  if (select count(*) from public.practice_log where user_id=u and practice_day=dd)>=3 then raise exception 'PRACTICE_LIMIT';end if;
  insert into public.practice_log(user_id,practice_day,career_id,task_id,completed_at,xp,coins)values(u,dd,c,task,t,10,15);
 elsif action='buy_skin' then
  select c.price into price from public.skin_catalog c where c.id=payload->>'skinId';
  if price is null then raise exception 'SKIN_INVALID';end if;
  if price=0 or exists(select 1 from public.skin_purchases where user_id=u and skin_id=payload->>'skinId') then return private.snapshot();end if;
  if private.funds(u)<price then raise exception 'COINS_INSUFFICIENT';end if;
  insert into public.skin_purchases(user_id,skin_id,coins) values(u,payload->>'skinId',price);
 elsif action='equip_skin' then
  select c.price into price from public.skin_catalog c where c.id=payload->>'skinId';
  if price is null then raise exception 'SKIN_INVALID';end if;
  if price>0 and not exists(select 1 from public.skin_purchases where user_id=u and skin_id=payload->>'skinId') then raise exception 'SKIN_NOT_OWNED';end if;
  update public.user_progress set equipped_skin_id=payload->>'skinId' where user_id=u;
 elsif action='buy_item' then
  select c.price into price from public.item_catalog c where c.id=payload->>'itemId';
  if price is null then raise exception 'ITEM_INVALID';end if;
  if jsonb_typeof(payload->'qty') is distinct from 'number' or (payload->>'qty')!~'^[1-9]$' or (payload->>'qty')::integer>9 then raise exception 'QTY_INVALID';end if;
  n:=(payload->>'qty')::integer;
  if private.funds(u)<price*n then raise exception 'COINS_INSUFFICIENT';end if;
  insert into public.item_purchases(user_id,item_id,qty,coins) values(u,payload->>'itemId',n,price*n);
 else
  select status into s from public.quest_progress where user_id=u and quest_id=q;
  if s is distinct from 'in_progress' or p.active_quest_id is distinct from q then raise exception 'QUEST_NOT_ACTIVE';end if;
  if coalesce(payload->>'battleId','')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
   if action='use_item' then raise exception 'BATTLE_INVALID';end if; battle:=null; else battle:=(payload->>'battleId')::uuid; end if;
  if action='use_item' then
   if not exists(select 1 from public.item_catalog where id=payload->>'itemId') then raise exception 'ITEM_INVALID';end if;
   if private.stock(u,payload->>'itemId')<1 then raise exception 'ITEM_OUT_OF_STOCK';end if;
   insert into public.item_uses(user_id,item_id,quest_id,battle_id) values(u,payload->>'itemId',q,battle);
  else
   -- boss_attempt: every answered question must be right; ×2 potions drunk in this fight let fewer answers win.
   if exists(select 1 from public.quest_steps t where t.quest_id=q and not exists(select 1 from public.checklist c where c.user_id=u and c.quest_id=q and c.step_id=t.id))then raise exception 'CHECKLIST_INCOMPLETE';end if;
   if exists(select 1 from public.boss_results where user_id=u and quest_id=q and passed_at is not null)then return private.snapshot();end if;
   select count(*) into total from public.boss_questions where quest_id=q;
   d:=case when battle is null then 0 else (select count(*) from public.item_uses where user_id=u and quest_id=q and battle_id=battle and item_id='double') end;
   if total=0 or jsonb_typeof(answers) is distinct from 'object' then raise exception 'BOSS_ANSWERS_INVALID';end if;
   select count(*) into h from jsonb_object_keys(answers);
   if h<1 or h>total or (d=0 and h<>total) or exists(select 1 from jsonb_object_keys(answers) k where not exists(select 1 from public.boss_questions b where b.quest_id=q and b.id=k))
    or exists(select 1 from public.boss_questions b where b.quest_id=q and answers ? b.id and (jsonb_typeof(answers->b.id) is distinct from 'number' or (answers->>b.id)!~'^[0-9]$' or (answers->>b.id)::integer>=jsonb_array_length(b.options)))then raise exception 'BOSS_ANSWERS_INVALID';end if;
   select count(*) into score from public.boss_questions b join private.boss_answers a on a.question_id=b.id where b.quest_id=q and answers ? b.id and (answers->>b.id)::integer=a.answer;
   if score=h and score+least(d,score)>=total then score:=total; else score:=least(score,total-1); end if;
   insert into public.boss_results(user_id,quest_id,score,attempts,passed_at,total) values(u,q,score,1,case when score=total then clock_timestamp() end,total)
    on conflict(user_id,quest_id) do update set score=excluded.score,total=excluded.total,attempts=public.boss_results.attempts+1,passed_at=excluded.passed_at;
  end if;
 end if;
 update public.user_progress set revision=revision+1 where user_id=u;
 return private.snapshot();
end $$;
revoke all on function private.shop_command(text,jsonb) from public,anon,authenticated;
grant execute on function private.shop_command(text,jsonb) to authenticated;
create or replace function public.liferpg_command(action text,payload jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.shop_command(action,payload);$$;
